-- 083: Nevşehir ilinin öne çıkan müze ve ören yerleri; bariz boş etiket temizliği.
with seed(name, category, place_type, city, address, latitude, longitude, slug, short_description, long_description, source_url, external_source, verified, trust_score, is_active, content_review_status, tags) as (values
('Göreme Açık Hava Müzesi','history','museum','Nevşehir','Göreme, Nevşehir',38.6408,34.8455,'nevsehir-goreme-acik-hava-muzesi','Kaya kiliseleri, şapelleri ve freskleriyle Kapadokya’nın en önemli tarihî alanlarından biri.','Göreme’deki kaya yerleşimlerinde manastır yaşamına ait kiliseler, şapeller ve ortak kullanım mekânları bulunur. Alan UNESCO Dünya Mirası kapsamındaki Kapadokya kültürel peyzajının parçasıdır. Ziyaret öncesi resmî erişim ve bilet bilgisini kontrol edin.','https://dosim.ktb.gov.tr/TR-321208/nevsehir.html','curated_seed',true,95,true,'source_backed',jsonb_build_array('Göreme','UNESCO','kaya kiliseleri','Kapadokya')),
('Derinkuyu Yeraltı Şehri','history','archaeological_site','Nevşehir','Derinkuyu, Nevşehir',38.3750,34.7333,'nevsehir-derinkuyu-yeralti-sehri','Derin katlara yayılan yaşam, depolama ve savunma alanlarıyla tanınan yeraltı yerleşimi.','Kapadokya’nın yeraltı yerleşimleri arasında öne çıkan Derinkuyu, kaya içine oyulmuş çok katlı mekânlarıyla bölgenin tarihî yaşam biçimini gösterir. Ziyaret alanının açık bölümleri ve saatleri değişebileceğinden resmî bilgiyi kontrol edin.','https://dosim.ktb.gov.tr/TR-321208/nevsehir.html','curated_seed',true,95,true,'source_backed',jsonb_build_array('yeraltı şehri','arkeoloji','Kapadokya')),
('Kaymaklı Yeraltı Şehri','history','archaeological_site','Nevşehir','Kaymaklı, Nevşehir',38.4610,34.7500,'nevsehir-kaymakli-yeralti-sehri','Tüneller ve birbirine bağlı odalardan oluşan, Kapadokya’nın önemli yeraltı kentlerinden biri.','Kaymaklı Yeraltı Şehri, kaya içine oyulmuş yaşam ve depolama mekânlarıyla bölgenin yeraltı mimarisini tanıtır. Dar geçitler bulunabileceği için ziyaret sırasında alanın yönlendirmelerine uyulmalıdır.','https://dosim.ktb.gov.tr/TR-321208/nevsehir.html','curated_seed',true,94,true,'source_backed',jsonb_build_array('yeraltı şehri','arkeoloji','Kapadokya')),
('Paşabağları ve Zelve Ören Yeri','history','archaeological_site','Nevşehir','Paşabağları, Avanos, Nevşehir',38.6750,34.8540,'nevsehir-pasabaglari-zelve-oren-yeri','Peri bacaları, kaya yerleşimleri ve tarihî yaşam alanlarını bir arada sunan Kapadokya ören yeri.','Zelve Vadisi eski kaya yerleşimleriyle, Paşabağları ise karakteristik peri bacalarıyla tanınır. Alan, Kapadokya’nın doğal oluşumları ile insan yerleşimi tarihini birlikte görme olanağı sağlar.','https://goturkiye.com/tr/nevsehir/nevsehir-rotalari','curated_seed',true,94,true,'source_backed',jsonb_build_array('peri bacaları','kaya yerleşimi','Kapadokya')),
('Hacı Bektaş Veli Müzesi','culture','museum','Nevşehir','Zir Mahallesi, Hacıbektaş, Nevşehir',38.9400,34.5570,'nevsehir-haci-bektas-veli-muzesi','Hacı Bektaş Veli külliyesi içinde yer alan, Anadolu’nun kültür ve inanç tarihi açısından önemli müze.','Külliye; türbe, tarihî yapılar ve ziyaret alanlarından oluşur. Müze ve külliyenin tarihî bölümleri için Kültür Portalı ve müze müdürlüğünün güncel ziyaret bilgileri esas alınmalıdır.','https://kulturportali.gov.tr/turkiye/nevsehir/gezilecekyer/hacibektas-vel-muzes','curated_seed',true,94,true,'source_backed',jsonb_build_array('Hacıbektaş','kültür tarihi','müze'))
)
insert into public.places(name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,verified,trust_score,is_active,content_review_status,tags)
select s.* from seed s
where not exists(select 1 from public.places p where p.slug=s.slug)
and not exists(select 1 from public.places p where p.city=s.city and lower(trim(p.name))=lower(trim(s.name)));

update public.places set name='Nevşehir Kayaşehir Yeraltı Şehri',source_url='https://goturkiye.com/tr/nevsehir/nevsehir-rotalari',short_description='Nevşehir Kalesi çevresindeki kaya içine oyulmuş tarihî yerleşim ve ziyaret alanı.',verified=true,trust_score=greatest(coalesce(trust_score,0),88),content_review_status='source_backed' where city='Nevşehir' and slug='osm-node-12875436601' and is_active=true;

update public.places set is_active=false,content_review_status='rejected' where city='Nevşehir' and slug in ('osm-node-10604097575','osm-node-10604097574') and is_active=true;
